import React, { useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';
import {
  CheckCircle2,
  Clock,
  CreditCard,
  Download,
  MapPin,
  Package,
  Phone,
  Printer,
  Search,
  Truck,
  User,
  XCircle,
} from 'lucide-react';
import { useAdmin } from '../lib/store';
import {
  Avatar,
  Badge,
  Drawer,
  EmptyState,
  MapView,
  OrderStatusBadge,
  PageHeader,
  cn,
} from '../lib/ui';
import { formatUZS, type Order, type OrderStatus } from '../lib/mock';

const tabs: Array<{ key: 'all' | OrderStatus; label: string }> = [
  { key: 'all', label: 'all' },
  { key: 'new', label: 'new' },
  { key: 'confirmed', label: 'confirmed' },
  { key: 'preparing', label: 'preparing' },
  { key: 'delivering', label: 'delivering' },
  { key: 'delivered', label: 'delivered' },
  { key: 'cancelled', label: 'cancelled' },
];

const flow: OrderStatus[] = ['new', 'confirmed', 'preparing', 'delivering', 'delivered'];

export const Orders = () => {
  const { t } = useTranslation();
  const { orders, couriers, assignCourier, updateOrderStatus, notify } = useAdmin();
  const [params, setParams] = useSearchParams();
  const [tab, setTab] = useState<'all' | OrderStatus>('all');
  const [query, setQuery] = useState('');
  const [payment, setPayment] = useState('all');
  const [selected, setSelected] = useState<Order | null>(null);
  const [courierChoice, setCourierChoice] = useState('');

  useEffect(() => {
    const orderId = params.get('order');
    if (orderId) {
      const found = orders.find((o) => o.id === orderId);
      if (found) setSelected(found);
    }
  }, [params, orders]);

  const filtered = useMemo(() => {
    let list = [...orders];
    if (tab !== 'all') list = list.filter((o) => o.status === tab);
    if (payment !== 'all') list = list.filter((o) => o.payment === payment);
    const q = query.trim().toLowerCase();
    if (q) list = list.filter((o) => `${o.id} ${o.customer} ${o.phone}`.toLowerCase().includes(q));
    return list;
  }, [orders, tab, payment, query]);

  const open = (order: Order) => {
    setSelected(order);
    setCourierChoice(order.courierId ?? '');
    setParams({ order: order.id });
  };

  const close = () => {
    setSelected(null);
    setParams({});
  };

  const setStatus = (status: OrderStatus) => {
    if (!selected) return;
    updateOrderStatus(selected.id, status);
    setSelected({ ...selected, status });
    notify(`${t('orders')} #${selected.id}: ${t(status)}`);
  };

  const assign = () => {
    if (!selected || !courierChoice) return;
    assignCourier(selected.id, courierChoice);
    setSelected({ ...selected, courierId: courierChoice, status: selected.status === 'new' ? 'confirmed' : selected.status });
    notify(t('assigned'));
  };

  const exportCsv = () => {
    const rows = [
      ['Order', 'Customer', 'Phone', 'Address', 'Total', 'Status', 'Payment'],
      ...filtered.map((o) => [o.id, o.customer, o.phone, o.address, String(o.total), o.status, o.payment]),
    ];
    const csv = rows.map((r) => r.map((v) => `"${v.replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'maxshop-orders.csv';
    a.click();
    URL.revokeObjectURL(url);
    notify('CSV yuklab olindi', 'info');
  };

  const courier = selected ? couriers.find((c) => c.id === selected.courierId) : undefined;
  const currentStep = selected ? flow.indexOf(selected.status) : -1;

  return (
    <div className="animate-fade-up">
      <PageHeader
        title={t('ordersTitle')}
        subtitle={t('ordersSubtitle')}
        action={
          <button className="btn-secondary btn-sm" onClick={exportCsv}>
            <Download size={15} /> {t('export')}
          </button>
        }
      />

      <div className="card p-4 sm:p-5">
        <div className="mb-4 flex gap-1 overflow-x-auto pb-1">
          {tabs.map((item) => {
            const count = item.key === 'all' ? orders.length : orders.filter((o) => o.status === item.key).length;
            return (
              <button
                key={item.key}
                onClick={() => setTab(item.key)}
                className={cn(
                  'flex shrink-0 items-center gap-2 rounded-xl px-3.5 py-2 text-xs font-bold transition',
                  tab === item.key ? 'bg-brand-600 text-white shadow-sm' : 'text-[var(--muted)] hover:bg-[var(--surface-2)]',
                )}
              >
                {t(item.label)}
                <span className={cn('rounded-full px-1.5 py-0.5 text-[10px]', tab === item.key ? 'bg-white/20' : 'bg-[var(--surface-3)]')}>{count}</span>
              </button>
            );
          })}
        </div>

        <div className="mb-4 flex flex-col gap-2 sm:flex-row">
          <div className="relative flex-1">
            <Search size={17} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
            <input className="input pl-10" placeholder="Buyurtma, mijoz yoki telefon..." value={query} onChange={(e) => setQuery(e.target.value)} />
          </div>
          <select className="select sm:w-48" value={payment} onChange={(e) => setPayment(e.target.value)}>
            <option value="all">{t('payment')}: {t('all')}</option>
            <option value="paid">{t('paid')}</option>
            <option value="pending">{t('pending')}</option>
            <option value="refunded">{t('refunded')}</option>
          </select>
        </div>

        {filtered.length === 0 ? (
          <EmptyState title={t('noData')} description="Ushbu filtr bo'yicha buyurtma topilmadi." />
        ) : (
          <div className="table-wrap">
            <table className="data-table min-w-[900px]">
              <thead>
                <tr>
                  <th>{t('order')}</th>
                  <th>{t('customer')}</th>
                  <th>{t('items')}</th>
                  <th>{t('total')}</th>
                  <th>{t('payment')}</th>
                  <th>{t('status')}</th>
                  <th>{t('courier')}</th>
                  <th className="text-right">{t('actions')}</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((order) => {
                  const c = couriers.find((x) => x.id === order.courierId);
                  return (
                    <tr key={order.id} className="cursor-pointer" onClick={() => open(order)}>
                      <td>
                        <p className="text-xs font-extrabold">#{order.id}</p>
                        <p className="mt-0.5 text-[10px] text-[var(--muted)]">{order.createdAt}</p>
                      </td>
                      <td>
                        <div className="flex items-center gap-2.5">
                          <Avatar emoji="🧑" size="sm" />
                          <div>
                            <p className="text-xs font-bold">{order.customer}</p>
                            <p className="text-[10px] text-[var(--muted)]">{order.phone}</p>
                          </div>
                        </div>
                      </td>
                      <td>
                        <div className="flex -space-x-1.5">
                          {order.items.slice(0, 3).map((it, i) => (
                            <span key={i} className="flex h-7 w-7 items-center justify-center rounded-lg bg-[var(--surface-3)] text-sm ring-2 ring-[var(--surface)]">{it.emoji}</span>
                          ))}
                          {order.items.length > 3 && (
                            <span className="flex h-7 w-7 items-center justify-center rounded-lg bg-[var(--surface-3)] text-[9px] font-bold ring-2 ring-[var(--surface)]">+{order.items.length - 3}</span>
                          )}
                        </div>
                      </td>
                      <td className="text-xs font-extrabold">{formatUZS(order.total)}</td>
                      <td>
                        <Badge tone={order.payment === 'paid' ? 'success' : order.payment === 'pending' ? 'warning' : 'danger'}>
                          {order.method === 'card' ? t('card') : t('cash')} · {t(order.payment)}
                        </Badge>
                      </td>
                      <td><OrderStatusBadge status={order.status} /></td>
                      <td>
                        {c ? (
                          <span className="flex items-center gap-1.5 text-xs font-semibold"><span>{c.emoji}</span>{c.name.split(' ')[0]}</span>
                        ) : (
                          <Badge tone="warning">{t('unassigned')}</Badge>
                        )}
                      </td>
                      <td>
                        <div className="flex justify-end">
                          <button className="btn-secondary btn-sm" onClick={(e) => { e.stopPropagation(); open(order); }}>
                            {t('details')}
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
        <p className="mt-4 text-xs font-semibold text-[var(--muted)]">{filtered.length} ta buyurtma</p>
      </div>

      <Drawer open={!!selected} onClose={close} title={`${t('orderDetails')} #${selected?.id ?? ''}`}>
        {selected && (
          <div className="space-y-5">
            <div className="flex flex-wrap items-center justify-between gap-2">
              <OrderStatusBadge status={selected.status} />
              <div className="flex gap-1.5">
                <button className="btn-secondary btn-sm" onClick={() => window.print()}>
                  <Printer size={13} /> Chek
                </button>
                <button className="btn-secondary btn-sm" onClick={() => notify('Buyurtma nusxasi yaratildi', 'info')}>
                  <Package size={13} /> Nusxa
                </button>
              </div>
            </div>

            <div className="card-soft p-4">
              <p className="mb-3 text-[10px] font-extrabold uppercase tracking-wider text-[var(--muted)]">{t('timeline')}</p>
              <div className="flex items-center justify-between">
                {flow.map((step, i) => (
                  <React.Fragment key={step}>
                    <div className="flex flex-col items-center gap-1.5">
                      <div className={cn(
                        'flex h-8 w-8 items-center justify-center rounded-full text-[11px] font-extrabold',
                        i <= currentStep ? 'bg-brand-600 text-white' : 'bg-[var(--surface-3)] text-[var(--muted)]',
                        selected.status === 'cancelled' && 'bg-[var(--surface-3)] text-[var(--muted)]',
                      )}>
                        {i < currentStep ? '✓' : i + 1}
                      </div>
                      <span className="max-w-[54px] text-center text-[9px] font-bold leading-tight text-[var(--muted)]">{t(step)}</span>
                    </div>
                    {i < flow.length - 1 && <div className={cn('mx-1 h-0.5 flex-1', i < currentStep ? 'bg-brand-500' : 'bg-[var(--surface-3)]')} />}
                  </React.Fragment>
                ))}
              </div>
              {selected.status === 'cancelled' && (
                <p className="mt-3 rounded-xl bg-rose-500/10 p-2 text-center text-xs font-bold text-rose-500">Buyurtma bekor qilingan</p>
              )}
            </div>

            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
              <div className="card-soft p-3.5">
                <p className="mb-2 flex items-center gap-1.5 text-[10px] font-extrabold uppercase tracking-wider text-[var(--muted)]"><User size={12} /> {t('customerInfo')}</p>
                <p className="text-sm font-extrabold">{selected.customer}</p>
                <p className="mt-1 flex items-center gap-1.5 text-xs text-[var(--muted)]"><Phone size={12} /> {selected.phone}</p>
                <a href={`tel:${selected.phone.replace(/\s/g, '')}`} className="btn-secondary btn-sm mt-2 w-full"><Phone size={12} /> {t('call')}</a>
              </div>
              <div className="card-soft p-3.5">
                <p className="mb-2 flex items-center gap-1.5 text-[10px] font-extrabold uppercase tracking-wider text-[var(--muted)]"><MapPin size={12} /> {t('deliveryAddress')}</p>
                <p className="text-xs font-semibold leading-relaxed">{selected.address}</p>
                <p className="mt-1 flex items-center gap-1.5 text-xs text-[var(--muted)]"><Clock size={12} /> {selected.eta}</p>
                {selected.note && <p className="mt-2 rounded-lg bg-amber-500/10 p-2 text-[10px] font-semibold text-amber-600 dark:text-amber-300">💬 {selected.note}</p>}
              </div>
            </div>

            <div>
              <p className="mb-2 text-[10px] font-extrabold uppercase tracking-wider text-[var(--muted)]">{t('items')} ({selected.items.length})</p>
              <div className="space-y-2">
                {selected.items.map((it) => (
                  <div key={it.productId} className="flex items-center gap-3 rounded-xl border p-2.5" style={{ borderColor: 'var(--border)' }}>
                    <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[var(--surface-3)] text-base">{it.emoji}</span>
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-xs font-bold">{it.name}</p>
                      <p className="text-[10px] text-[var(--muted)]">{it.qty} × {formatUZS(it.price)}</p>
                    </div>
                    <p className="text-xs font-extrabold">{formatUZS(it.qty * it.price)}</p>
                  </div>
                ))}
              </div>
              <div className="mt-3 space-y-1.5 rounded-xl border p-3 text-xs" style={{ borderColor: 'var(--border)' }}>
                <div className="flex justify-between text-[var(--muted)]"><span>{t('subtotal')}</span><span>{formatUZS(selected.subtotal)}</span></div>
                <div className="flex justify-between text-[var(--muted)]"><span>{t('deliveryFee')}</span><span>{selected.deliveryFee ? formatUZS(selected.deliveryFee) : t('freeDelivery')}</span></div>
                {selected.discount > 0 && <div className="flex justify-between text-brand-600 dark:text-brand-400"><span>{t('discount')}</span><span>-{formatUZS(selected.discount)}</span></div>}
                <div className="flex justify-between border-t pt-2 text-sm font-extrabold" style={{ borderColor: 'var(--border)' }}><span>{t('total')}</span><span>{formatUZS(selected.total)}</span></div>
              </div>
            </div>

            <div>
              <p className="mb-2 flex items-center gap-1.5 text-[10px] font-extrabold uppercase tracking-wider text-[var(--muted)]"><Truck size={12} /> {t('assignCourier')}</p>
              <div className="flex gap-2">
                <select className="select" value={courierChoice} onChange={(e) => setCourierChoice(e.target.value)}>
                  <option value="">{t('unassigned')}</option>
                  {couriers.map((c) => (
                    <option key={c.id} value={c.id}>{c.name} · {c.vehicle} · ⭐ {c.rating}</option>
                  ))}
                </select>
                <button className="btn-primary shrink-0" onClick={assign} disabled={!courierChoice}>{t('assignCourier')}</button>
              </div>
              {courier && (
                <div className="mt-2 flex items-center gap-2 rounded-xl bg-brand-500/10 p-2 text-xs font-bold text-brand-700 dark:text-brand-300">
                  <span>{courier.emoji}</span> {courier.name} · {courier.phone}
                </div>
              )}
            </div>

            <div>
              <p className="mb-2 text-[10px] font-extrabold uppercase tracking-wider text-[var(--muted)]">{t('updateStatus')}</p>
              <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
                {(['confirmed', 'preparing', 'delivering', 'delivered', 'cancelled'] as OrderStatus[]).map((status) => (
                  <button
                    key={status}
                    onClick={() => setStatus(status)}
                    className={cn(
                      'btn-secondary btn-sm justify-start',
                      selected.status === status && 'border-brand-500 text-brand-600 dark:text-brand-400',
                      status === 'cancelled' && 'text-rose-500',
                    )}
                  >
                    {status === 'cancelled' ? <XCircle size={13} /> : <CheckCircle2 size={13} />} {t(status)}
                  </button>
                ))}
              </div>
            </div>

            <div>
              <p className="mb-2 flex items-center gap-1.5 text-[10px] font-extrabold uppercase tracking-wider text-[var(--muted)]"><MapPin size={12} /> {t('delivery')}</p>
              <MapView couriers={couriers} order={selected} height={220} />
            </div>

            <div className="flex items-center gap-2 rounded-xl bg-[var(--surface-2)] p-3 text-xs">
              <CreditCard size={16} className="text-brand-500" />
              <span className="flex-1 font-semibold">{selected.method === 'card' ? t('card') : t('cash')}</span>
              <Badge tone={selected.payment === 'paid' ? 'success' : selected.payment === 'pending' ? 'warning' : 'danger'}>{t(selected.payment)}</Badge>
            </div>
          </div>
        )}
      </Drawer>
    </div>
  );
};
